// бил единайсети препис на едно и също нещо и би излизал само
// на славянски; като препратка идва наготово на всеки превод,
// който човекът е свалил. (Идея на потребителя, 11.09.2026.)
//
// ⚠ `trim` е (отрязано отпред, отрязано отзад) В ЗНАЦИ и е
// РАЗЛИЧНО за всеки превод. За църковнославянския се МЕРИ
// (текстът на прокимена е същият, само в друга графика); за
// българския се пренася по дял от стиха и препинателна
// граница, а 13 случая са нанесени на ръка. За останалите
// преводи отрязване НЯМА и се показва целият стих — по
// правилото при цитатите: по-добре малко повече, отколкото
// откъс, срязан насред дума.

/// Едно място от Писанието с отрязване по език.
class P {
  final String ref;
  /// ⚠ Само за българския и само където номерацията се
  /// разминава — виж „Номерацията на псалмите" в README-то.
  final String? bgRef;
  final Map<String, List<int>> trim;
  const P({required this.ref, this.bgRef,
      this.trim = const {}});
}

/// Прокимен: глас, самият той и стиховете му.
class K {
  final int? glas;
  final P text;
  final List<P> verses;
  /// Зачалата, които книгата дава за ТАЗИ памет.
  ///
  /// ⚠⚠ ТЕ СА ПОТВЪРЖДЕНИЕТО, че четивото е на тази памет, а
  /// не редовото за деня: мерено, при 204 от 323 дни с памет
  /// в месецослова четивото все пак е редовото.
  final List<int> zachala;
  const K(this.glas, this.text, this.verses, this.zachala);
}

